{
  "name": "opencode-voice-tui",
  "version": "1.0.0",
  "description": "Voice plugin for OpenCode (TUI): speak your prompt, Whisper (whisper.cpp) transcribes it on the GPU, and an LLM (local Ollama or OpenCode's own) cleans up the text.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "voice",
    "speech-to-text",
    "whisper",
    "whisper.cpp",
    "ollama",
    "tui"
  ],
  "exports": {
    "./tui": "./src/tui.tsx"
  },
  "files": ["src", "README.pt-BR.md"],
  "scripts": {
    "test": "node --test test/*.test.ts"
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.6"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opentui/core": "^0.8.4",
    "@opentui/solid": "^0.8.4",
    "@types/node": "^26.6.6",
    "solid-js": "^1.9.9",
    "typescript": "^7.0.2"
  }
}
